const fs = require('fs');
const html = fs.readFileSync('manic_miner.html', 'utf8');
const m = html.match(/<script[\s\S]*?>([\s\S]*?)<\/script>/);
const js = m[1];

// Tokenizer: strip strings/comments, then count braces/parens per line
function analyze(line) {
  let depth = 0, minD = 0;
  const pairs = { '{':0, '}':0, '(':0, ')':0 };
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    // Single-line comment
    if (ch === '/' && i+1 < line.length && line[i+1] === '/') break;
    // Multi-line comment
    if (ch === '/' && i+1 < line.length && line[i+1] === '*') {
      const end = line.indexOf('*/', i+2);
      i = end >= 0 ? end + 1 : line.length;
      continue;
    }
    // Double-quoted string
    if (ch === '"') {
      i++;
      while (i < line.length) {
        if (line[i] === '\\') { i += 2; continue; }
        if (line[i] === '"') { i++; break; }
        i++;
      }
      continue;
    }
    // Single-quoted string
    if (ch === "'") {
      i++;
      while (i < line.length) {
        if (line[i] === '\\') { i += 2; continue; }
        if (line[i] === "'") { i++; break; }
        i++;
      }
      continue;
    }
    // Template literal with ${} tracking
    if (ch === '`') {
      i++;
      while (i < line.length && line[i] !== '`') {
        if (line[i] === '\\') { i += 2; continue; }
        if (line[i] === '$' && i+1 < line.length && line[i+1] === '{') {
          // ${ — the { is a real brace, but skip the $ and let normal counting handle the {
          pairs['{']++; depth++; i += 2; continue;
        }
        i++;
      }
      if (i < line.length) i++;
      continue;
    }
    // Braces/parens
    if (ch === '{' || ch === '(') { pairs[ch]++; depth++; }
    else if (ch === '}' || ch === ')') { 
      depth--; 
      pairs[ch]++; 
      if (depth < minD) minD = depth; 
    }
  }
  return { net: depth, minD, pairs };
}

const lines = js.split('\n');
let globalDepth = 0;
console.log("=== Per-line brace/paren balance ===");
for (let i = 0; i < lines.length; i++) {
  const r = analyze(lines[i]);
  if (r.net !== 0 || r.minD < 0) {
    console.log(`Line ${i+1}: depth=${globalDepth} net=${r.net} after=${globalDepth+r.net} minDepth=${r.minD}`);
    const bo = Object.entries(r.pairs).map(([k,v]) => `${k}:${v}`).join(' ');
    console.log(`  brackets: ${bo}`);
  }
  globalDepth += r.net;
}
console.log(`Final depth: ${globalDepth}`);

