#!/usr/bin/env python3
# Proper tokenizer with no compound statements on single lines

import subprocess
import sys

def strip_strings(line):
    result = []
    i = 0
    while i < len(line):
        ch = line[i]

        # Single-line comment: skip to end of line
        if ch == '/' and i + 1 < len(line) and line[i+1] == '/':
            break

        # Multi-line comment: skip until */
        if ch == '/' and i + 1 < len(line) and line[i+1] == '*':
            end = line.find('*/', i + 2)
            if end >= 0:
                i = end + 1
            else:
                i = len(line) - 1
            continue

        # Double-quoted string: skip content, don't count braces
        if ch == '"':
            i += 1
            while i < len(line):
                if line[i] == '\\':
                    i += 2
                    continue
                if line[i] == '"':
                    i += 1
                    break
                i += 1
            continue

        # Single-quoted string: skip content, don't count braces  
        if ch == "'":
            i += 1
            while i < len(line):
                if line[i] == '\\':
                    i += 2
                    continue
                if line[i] == "'":
                    i += 1
                    break
                i += 1
            continue

        # Template literal with ${} expression tracking
        bt = chr(96)  # backtick
        if ch == bt:
            i += 1
            while i < len(line) and line[i] != bt:
                if line[i] == '\\':
                    i += 2
                    continue
                # ${ starts a template expression - count the { as real brace
                if line[i] == '$' and i + 1 < len(line) and line[i+1] == '{':
                    i += 1  # skip $, normal code below counts the {
                    continue
                i += 1
            if i < len(line):
                i += 1  # skip closing backtick
            continue

        # Regular brace counting
        if ch == '{':
            result.append('{')
        elif ch == '}':
            result.append('}')

        i += 1

    return ''.join(result)

def count_braces(line):
    depth = 0
    min_depth = 0

    stripped = strip_strings(line)

    for ch in stripped:
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth < min_depth:
                min_depth = depth

    return depth, min_depth

def main():
    # Read the HTML file and extract JS block
    html = open('manic_miner.html').read()

    parts = html.split('\n<script')
    if len(parts) < 2:
        print("ERROR: No script tag found")
        return

    js_block = parts[1].split('</script>')[0]

    # Split into lines (handle both \r\n and \n)
    js_lines = js_block.replace('\r', '').split('\n')

    print("JS block has %d lines" % len(js_lines))

    # Count braces through all lines, tracking global depth
    global_depth = 0

    for idx in range(len(js_lines)):
        line = js_lines[idx]
        net, mn = count_braces(line)
        old_depth = global_depth
        global_depth += net

        if net != 0 or mn < 0:
            marker = ""
            if mn < 0:
                marker = " ***NEG DEPTH***"

            print("JS line %d (HTML ~%d): depth=%+d net=%+d -> %+d%s" % (
                idx + 1, idx + 30, old_depth, net, global_depth, marker
            ))

    print("")
    print("Final brace depth: %d" % global_depth)

    # Now run node --check to get exact error position
    with open('_chk.js', 'w') as f:
        f.write(js_block.replace('\r', ''))

    result = subprocess.run(
        ['node', '--check', '_chk.js'],
        capture_output=True,
        text=True,
        timeout=5
    )

    print("")
    print("=== Node --check output ===")
    for line in result.stderr.split('\n')[:10]:
        print(line)

if __name__ == '__main__':
    main()

