const fs = require('fs');
const code = fs.readFileSync('manic_miner.html', 'utf8').split('\n');
let cum = 0;
for (let i = 0; i < code.length; i++) {
    const line = code[i];
    let opens = 0, closes = 0;
    // We need to skip string contents and template literal interpolation
    // For a minified one-liner this is hard, but let's do simple counting
    for (let c = 0; c < line.length; c++) {
        if (line[c] === '{') opens++;
        if (line[c] === '}') closes++;
    }
    cum += opens - closes;
    if (opens !== closes || Math.abs(cum) > 2) {
        console.log(`Line ${i+1}: open=${opens} close=${closes} cum_after=${cum}`);
    }
}
console.log(`Total cumulative: ${cum}`);

