function countBracesIgnoreStrings(s) {
    let open = 0, close = 0;
    let i = 0;
    while (i < s.length) {
        const c = s[i];
        if ((c === '"' || c === "'") && (i === 0 || s[i-1] !== '\\')) {
            // Skip string literal
            i++;
            while (i < s.length && s[i] !== c && s[i] !== '\n') {
                if (s[i] === '\\' && i + 1 < s.length) i++;
                i++;
            }
            if (i < s.length) i++; // skip closing quote
        } else if (c === '`' && (i === 0 || s[i-1] !== '\\')) {
            // Skip template literal
            i++;
            while (i < s.length && s[i] !== '`') {
                if (s[i] === '\\' && i + 1 < s.length) i++;
                i++;
            }
            if (i < s.length) i++; // skip closing backtick
        } else if (c === '{') open++;
        else if (c === '}') close++;
        i++;
    }
    return {open, close};
}

// Show detailed brace count for each method in the Level class
for (let i = 84; i <= 97; i++) {
    if (i < code.length) {
        const b = countBracesIgnoreStrings(code[i]);
        console.log(`Line ${i+1}: open=${b.open} close=${b.close} diff=${b.open-b.close}`);
    }
}

// Total
let totO = 0, totC = 0;
for (const line of code) {
    const b = countBracesIgnoreStrings(line);
    totO += b.open; totC += b.close;
}
console.log(`Total: open=${totO} close=${totC} diff=${totO-totC}`);

// Show cumulative 
