function countBracesIgnoringStrings(s) {
    let open = 0, close = 0;
    let i = 0;
    while (i < s.length) {
        const c = s[i];
        if ((c === '"' || c === "'") && (i === 0 || s[i-1] !== '\\')) {
            i++;
            while (i < s.length && s[i] !== c && s[i] !== '\n' && s[i] !== '\r') {
                if (s[i] === '\\' && i + 1 < s.length) i++;
                i++;
            }
            if (i < s.length) i++;
        } else if (c === '`' && (i === 0 || s[i-1] !== '\\')) {
            i++;
            while (i < s.length && s[i] !== '`') {
                if (s[i] === '\\' && i + 1 < s.length) i++;
                i++;
            }
            if (i < s.length) i++;
        } else if (c === '{') open++;
        else if (c === '}') close++;
        i++;
    }
    return {open, close};
}

let cum = 0;
for (let i = 102; i <= 140; i++) {
