}).join('\n');

console.log("Raw:", rawBlock.length, "Filtered:", filteredCode.length);

try {
    vm.runInContext(filteredCode, sandbox, { timeout: 10000 });
    console.log("Script init OK");
} catch(e) {
    console.log("Init ERROR:", e.name, ":", e.message);

    // Find which source line caused this
    const allLines = rawBlock.split('\n');
    for (let i = Math.max(0, allLines.length - 20); i < allLines.length; i++) {
        if (i < 50) continue; // skip past declarations
        console.log(`L${i+1}: ${allLines[i].substring(0,100)}`);
    }
    process.exit(1);
}

console.log("\nAfter init:");
console.log("  startGame type:", typeof sandbox.startGame);
console.log("  gameLoop type:", typeof sandbox.gameLoop);
console.log("  currentLevelObj:", sandbox.currentLevelObj === null ? "null" : (sandbox.currentLevelObj === undefined ? "undefined" : "exists"));

if (typeof sandbox.startGame !== "function") {
    console.log("\nPROBLEM: startGame is not defined as a function!");
    // List all defined functions
    const funcMatches = [...filteredCode.matchAll(/function\s+(\w+)/g)];
    console.log("Functions defined:", funcMatches.map(m => m[1]));
    process.exit(1);
}

try {
    console.log("\nCalling startGame()...");
