    console.log("gameState:", sandbox.gameState);
} catch(e) {
    console.log("startGame error:", e.name, ":", e.message);
}

if (pending.length > 0) {
    console.log("\nPumping frames...");
    let framesRun = 0;
    try {
        while (pending.length > 0 && framesRun < 30) {
            const cb = pending.shift();
            cb(framesRun * 16.7);
            framesRun++;
        }
        console.log("OK: ran", framesRun, "frames");
        console.log(JSON.stringify({ ok: true, error: null, frames_run: framesRun, started: true }));
    } catch(e) {
        console.log("Frame error:", e.name, ":", e.message);
        console.log(JSON.stringify({ ok: false, error: "frame " + framesRun + ": " + e.name + ": " + e.message, frames_run: framesRun, started: true }));
    }
} else {
    console.log("No pending frames!");
    console.log(JSON.stringify({ ok: false, error: "no animation frame was ever scheduled", frames_run: 0, started: false }));
}

