function countBraces(line) {
  let depth = 0;
  let i = 0;
  while (i < line.length) {
    const ch = line[i];
    // Skip escaped chars
    if (ch === '\\\\' && i+1 < line.length) { i += 2; continue; }
    // Single-quoted strings
    if (ch === \"'\") {
      i++;
      while (i < line.length && line[i] !== \"'\") { 
        if (line[i] === '\\\\') i++; 
        i++;
      }
      i++;
      continue;
    }
    // Double-quoted strings
    if (ch === '\"') {
      i++;
      while (i < line.length && line[i] !== '\"') {
        if (line[i] === '\\\\') i++;
        i++;
      }
      i++;
      continue;
    }
    // Template literals
    if (ch === '\u0060') {
      i++;
      while (i < line.length && line[i] !== '\u0060') {
        if (line[i] === '\\\\') i++;
        i++;
      }
      i++;
      continue;
    }
    if (ch === '{') depth++;
    else if (ch === '}') depth--;
    i++;
  }
  return depth;
}

