def balance_braces(s):
    bal = 0
    pos_by_line = {}
    i = 0
    in_string = None  # None, "'", '"', or '`'
    while i < len(s):
        ch = s[i]
        if in_string:
            if ch == '\\' and i + 1 < len(s):
                i += 2
                continue
            if ch == in_string:
                in_string = None
            i += 1
            continue
        if ch in ("'", '"', '`'):
            # Check for escaped quotes in single/double quotes
            if ch == "'" and '\\' not in s[max(0,i-3):i]:
                # Simple check: find matching close quote (not preceded by backslash)
                end = s.find("'", i + 1)
                if end == -1:
                    i = len(s)
                else:
                    i = end + 1
                continue
            elif ch == '"' and '\\' not in s[max(0,i-3):i]:
                end = s.find('"', i + 1)
                if end == -1:
                    i = len(s)
                else:
                    i = end + 1
                continue
            elif ch == '`':
                # Find matching backtick (simplified - doesn't handle nested ${})
                end = s.find('`', i + 1)
                if end == -1:
                    i = len(s)
                else:
                    i = end + 1
                continue
        if ch == '{':
            bal += 1
        elif ch == '}':
            bal -= 1
        i += 1
    return bal, None

